def is_prime(num):
    """Determine if a number is prime."""
    if num <= 1:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True


def primes_up_to(n):
    """Return a list of all prime numbers up to n."""
    return [i for i in range(2, n+1) if is_prime(i)]


def nth_prime(n):
    """Return the nth prime number."""
    count = 0
    num = 1
    while count < n:
        num += 1
        if is_prime(num):
            count += 1
    return num

